'use client';

import { useEffect, useRef, type ReactNode } from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './scroll-velocity-skew.css';

export interface VelocityScrollerProps {
  children: ReactNode;
  /** Accessible name for the scroll area. */
  label: string;
  /** Largest skew, in degrees. */
  maxSkew?: number;
  className?: string;
}

/**
 * A scroll area that measures how fast it is moving. Fast scrolling leans
 * the decorative `SkewStrip`s inside it (up to `maxSkew`), and they ease
 * back to straight when scrolling stops. Body text is never transformed.
 */
export function VelocityScroller({
  children,
  label,
  maxSkew = 6,
  className = '',
}: VelocityScrollerProps) {
  const el = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useEffect(() => {
    const node = el.current;
    if (!node || reduced) {
      node?.style.setProperty('--mg-skew', '0deg');
      return;
    }
    let last = node.scrollTop;
    let lastTime = performance.now();
    let skew = 0;
    let target = 0;
    let frame = 0;
    const tick = () => {
      // Ease toward the target, and let the target relax to zero.
      skew += (target - skew) * 0.2;
      target *= 0.88;
      node.style.setProperty('--mg-skew', `${skew.toFixed(2)}deg`);
      frame =
        Math.abs(skew) > 0.02 || Math.abs(target) > 0.02
          ? requestAnimationFrame(tick)
          : 0;
      if (!frame) node.style.setProperty('--mg-skew', '0deg');
    };
    const onScroll = () => {
      const now = performance.now();
      const velocity = (node.scrollTop - last) / Math.max(8, now - lastTime);
      last = node.scrollTop;
      lastTime = now;
      target = Math.max(-maxSkew, Math.min(maxSkew, velocity * 3));
      if (!frame) frame = requestAnimationFrame(tick);
    };
    node.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      node.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(frame);
    };
  }, [maxSkew, reduced]);

  return (
    <div
      ref={el}
      className={`mg-velocity ${className}`}
      tabIndex={0}
      role='region'
      aria-label={label}
    >
      {children}
    </div>
  );
}

/** A decorative band that leans with scroll speed. Hidden from assistive tech. */
export function SkewStrip({ children }: { children?: ReactNode }) {
  return (
    <div className='mg-velocity__strip' aria-hidden='true'>
      {children}
    </div>
  );
}

.mg-velocity {
  --mg-skew: 0deg;
  height: 240px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 12px 14px;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 12px;
  background: #fff;
  color: #46527a;
}

.mg-velocity:focus-visible {
  outline: 3px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-velocity p {
  margin: 0 0 12px;
}

.mg-velocity__strip {
  margin: 16px -14px;
  padding: 10px 0;
  overflow: hidden;
  background: var(--mg-accent, #164cff);
  color: #fff;
  font-weight: 800;
  letter-spacing: 0.1em;
  white-space: nowrap;
  transform: skewY(var(--mg-skew));
}

.mg-velocity__strip:nth-of-type(even) {
  background: var(--mg-ink, #0c1738);
  color: var(--mg-green, #b6ff3b);
}

@media (prefers-reduced-motion: reduce) {
  .mg-velocity__strip {
    transform: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
